(function(root){
 const focus=['Host SW','AI Model Dev. Tools','Ref. Models','SDK Installer'];
 const valid=x=>/^\d{4}-\d{2}-\d{2}$/.test(x||'')&&!isNaN(Date.parse(x));
 const days=(a,b)=>valid(a)&&valid(b)?Math.round((Date.parse(a)-Date.parse(b))/86400000):null;
 function week(stamp){const d=new Date(stamp);if(isNaN(d))return '';const k=new Date(d.getTime()+9*3600000);k.setUTCHours(0,0,0,0);k.setUTCDate(k.getUTCDate()-((k.getUTCDay()+6)%7));return k.toISOString().slice(0,10);}
 function summarize(plan,id='current',observedAt=plan.observedAt||plan.modifiedAt){const groups={};for(const r of plan.rows){const s=groups[r.section]??={rows:0,tickets:[],statuses:{}};s.rows++;if(r.key&&!s.tickets.includes(r.key))s.tickets.push(r.key);s.statuses[r.status]=(s.statuses[r.status]||0)+1;}return {id,observedAt,sourceModifiedAt:plan.modifiedAt,name:plan.name,rowCount:plan.rows.length,focusRows:plan.rows.filter(r=>focus.includes(r.section)).length,groups,hasWorkbook:!!plan.workbookBase64};}
 function weekly(observations){const by=new Map();for(const o of [...observations].sort((a,b)=>a.observedAt.localeCompare(b.observedAt))){const w=week(o.observedAt);if(w)by.set(w,o);}if(!by.size)return [];const keys=[...by.keys()].sort(),out=[];for(let t=Date.parse(keys[0]);t<=Date.parse(keys.at(-1));t+=604800000){const w=new Date(t).toISOString().slice(0,10);out.push({week:w,observation:by.get(w)||null});}return out;}
 function legacyObservations(runs,rows){const current=new Map(rows.filter(r=>r.key).map(r=>[r.key,r.section]));return runs.map(run=>{const groups={};let total=0;const unique=new Map(run.records.filter(r=>!r.error).map(r=>[r.key,r]));for(const key of unique.keys()){const section=current.get(key);if(focus.includes(section)){total++;groups[section]??={rows:0};groups[section].rows++;}}return {id:String(run.id),observedAt:run.observedAt,focusRows:total,rowCount:unique.size,groups};});}
 function dependency(d,rows){const a=rows.filter(r=>r.key===d.predecessorKey),b=rows.filter(r=>r.key===d.successorKey);if(a.length!==1||b.length!==1)return {...d,a:a[0],b:b[0],risk:'unresolved',lag:null,overlap:null};const lag=days(a[0].due,b[0].due),overlap=days(a[0].due,b[0].preDue);return {...d,a:a[0],b:b[0],lag,overlap,risk:a[0].status==='Done'?'completed':lag>0?'conditional':overlap>0?'overlap':lag===null?'missing':'aligned'};}
 function changesFor(changes,rows){const keys=new Set(rows.map(r=>r.key).filter(Boolean));return changes.filter(c=>keys.has(c.key));}
 function warnings(rows,changes,deps,reviews,asOf){const out=[];const push=(kind,r,detail,severity='review')=>out.push({kind,row:r.row,key:r.key,title:r.title,owner:r.owner,detail,severity});
  const slips=new Map();for(const c of changes.filter(c=>c.kind==='slipped')){const k=c.key+'|'+c.field;const v=slips.get(k)||[];v.push(c);slips.set(k,v);}
  for(const r of rows){if(r.status==='Done')continue;
   if(valid(r.preDue)&&valid(r.due)&&r.preDue>r.due)push('Milestone order',r,'P-D target '+r.preDue+' is after Feature Done target '+r.due+'. Verify milestone scope.','high');
   if(valid(r.due)&&r.due<asOf)push('Past Feature Done target',r,r.due+' passed; final completion is not recorded.','high');
   if(!['P-D','Done'].includes(r.status)&&valid(r.preDue)&&r.preDue<asOf)push('Past P-D target',r,r.preDue+' passed; pre-silicon completion is not recorded.','high');
   if(['D','R'].includes(r.status))push('Recorded delay / risk',r,'Workbook status: '+r.status,'high');
   const missing=[!valid(r.preDue)&&'P-D target',!valid(r.due)&&'Feature Done target',!r.owner&&'owner',r.status==='Unknown'&&'status'].filter(Boolean);if(missing.length)push('Missing data',r,'Not recorded: '+missing.join(', '));
   for(const field of ['preDue','due']){const list=slips.get(r.key+'|'+field)||[];if(list.length>=2)push('Repeated slippage',r,(field==='preDue'?'P-D':'Feature Done')+' target moved later '+list.length+' times in observed history; last '+list.at(-1).observedAt.slice(0,10)+'.','high');}
  }
  const keys=new Set(rows.map(r=>r.key));for(const d of deps){if(d.risk==='conditional'&&(keys.has(d.predecessorKey)||keys.has(d.successorKey))&&reviews.find(r=>r.id===d.id)?.decision!=='rejected')out.push({kind:'Conditional dependency',row:d.b.row,key:d.successorKey,title:d.successorTitle,owner:d.b.owner,detail:d.predecessorKey+' final target is '+d.lag+' days after '+d.successorKey+'. Unconfirmed dependency; validate required baseline and release.',severity:'conditional',dependencyId:d.id});}
  return out;
 }
 function diff(before,after){const map=rows=>{const m=new Map();for(const r of rows){const k=r.key?'ticket:'+r.key:'row:'+r.section+'|'+r.group+'|'+r.title;const list=m.get(k)||[];list.push(r);m.set(k,list);}return m;};const a=map(before.rows),b=map(after.rows),out=[];for(const k of new Set([...a.keys(),...b.keys()])){const x=a.get(k)||[],y=b.get(k)||[];if(x.length>1||y.length>1){out.push({key:k,title:(y[0]||x[0]).title,kind:'Ambiguous duplicate',detail:x.length+' → '+y.length+' matching rows; not automatically paired.'});continue;}if(!x.length||!y.length){out.push({key:(y[0]||x[0]).key,title:(y[0]||x[0]).title,kind:x.length?'Removed':'Added',detail:(y[0]||x[0]).section});continue;}for(const f of ['section','group','title','team','owner','status','preDue','due'])if(x[0][f]!==y[0][f])out.push({key:y[0].key,title:y[0].title,kind:f,detail:(x[0][f]||'Not recorded')+' → '+(y[0][f]||'Not recorded')});}return out;}
 const api={focus,valid,days,week,summarize,weekly,legacyObservations,dependency,changesFor,warnings,diff};root.HistoryCore=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
